//! How much invalid syntax the parser notices: corpus statements changed by
//! one token (dropped, doubled, swapped with the next), checked against
//! abaplint's statement grammar. A mutant abaplint takes for no statement
//! should be unknown to the parser or have a syntax error.
//!
//! Needs golden data generated by the oracle, otherwise the test is skipped:
//!   node tools/oracle.mjs --mutations tests/corpus/golden/mutations.json --list tests/corpus/corpora.txt

mod common;

use std::collections::BTreeMap;

use abap_syntax::check::syntax_error;
use abap_syntax::StatementKind;
use serde::Deserialize;

/// Baseline: every statement is matched against its grammar.
const MIN_REJECTED_PERCENT: f64 = 100.0;
/// Mutants abaplint takes for valid and the syntax check of an SAP system
/// rejects: a dash without a component (`sy- = 0`, `ls--comp`), `INTO INTO`,
/// a handler named FOR (`SET HANDLER h FOR.`), SHIFT DELETING without its
/// direction, WRITE and ULINE with a position that is no literal and no AT
/// (`WRITE a b`), `SELECT FROM t INTO` without FIELDS, a SELECT list with
/// blanks in strict mode, a parameter name longer than eight characters,
/// `strlen( )`, the PERFORM sections out of order, and the SELECT list of
/// two SELECTs with FROM dropped. Checked on the SAP trial (8.16) on
/// 2026-11-14: SAP accepted none of them; it reported a syntax error for
/// 211, an unknown name first for the rest, and the same constructs with
/// declared names as syntax errors.
const MAX_REPORTED: usize = 368;

#[derive(Deserialize)]
struct Mutant {
    /// abaplint's kind of the statement before the change
    kind: String,
    abap: String,
    /// abaplint's kinds of the statements of the mutant
    abaplint: Vec<String>,
}

#[derive(Default)]
struct PerKind {
    invalid: usize,
    rejected: usize,
    accepted: Vec<String>,
}

#[test]
fn mutants_abaplint_rejects() {
    let path = common::repo_root().join("tests/corpus/golden/mutations.json");
    let Ok(text) = std::fs::read_to_string(&path) else {
        println!("skipped: no golden data, see the comment at the top of this file");
        return;
    };
    let mutants: Vec<Mutant> = serde_json::from_str(&text).unwrap();
    let mut kinds: BTreeMap<String, PerKind> = BTreeMap::new();
    let mut reported = Vec::new();
    let mut other_kind = 0;
    let mut valid = 0;
    for m in &mutants {
        let [abaplint] = m.abaplint.as_slice() else {
            continue;
        };
        let file = abap_syntax::parse(&m.abap);
        let ours: Vec<_> = file
            .statements
            .iter()
            .filter(|s| s.kind != StatementKind::Comment)
            .collect();
        let reason = match ours.as_slice() {
            [s] if s.kind == StatementKind::Unknown => Some("unknown"),
            [s] => syntax_error(&file, s).map(|e| e.message),
            _ => Some("not one statement"),
        };
        let rejected = reason.is_some();
        if abaplint == "Unknown" {
            let k = kinds.entry(m.kind.clone()).or_default();
            k.invalid += 1;
            if rejected {
                k.rejected += 1;
            } else {
                k.accepted.push(m.abap.replace('\n', " "));
            }
        } else {
            valid += 1;
            if let Some(reason) = reason {
                reported.push(format!(
                    "{abaplint}, ours {reason}: {}",
                    m.abap.replace('\n', " ")
                ));
            } else if ours.first().is_some_and(|s| s.kind.as_str() != abaplint) {
                other_kind += 1;
            }
        }
    }

    let mut by_gap: Vec<_> = kinds.iter().collect();
    by_gap.sort_by_key(|(_, k)| std::cmp::Reverse(k.accepted.len()));
    println!("invalid mutants accepted, by the kind of the original statement:");
    for (kind, k) in by_gap
        .iter()
        .take(40)
        .filter(|(_, k)| !k.accepted.is_empty())
    {
        println!(
            "  {kind}: {}/{} rejected, {} accepted",
            k.rejected,
            k.invalid,
            k.accepted.len()
        );
        for a in k.accepted.iter().take(3) {
            println!("      {a}");
        }
    }
    println!("valid mutants reported as errors:");
    for r in reported.iter().take(20) {
        println!("  {r}");
    }
    let invalid: usize = kinds.values().map(|k| k.invalid).sum();
    let rejected: usize = kinds.values().map(|k| k.rejected).sum();
    let complete = kinds
        .values()
        .filter(|k| k.invalid > 0 && k.accepted.is_empty())
        .count();
    let rate = common::percent(rejected, invalid);
    println!(
        "\nmutants abaplint rejects: {rejected}/{invalid} rejected ({rate:.1}%), all of them for {complete} of {} statement kinds; mutants abaplint accepts: {valid}, reported as errors: {}, another kind: {other_kind}",
        kinds.len(),
        reported.len()
    );
    assert!(
        rate >= MIN_REJECTED_PERCENT,
        "{rate:.1}% below {MIN_REJECTED_PERCENT}%"
    );
    assert!(
        reported.len() <= MAX_REPORTED,
        "{} valid mutants reported, at most {MAX_REPORTED}",
        reported.len()
    );
}
